"""Basic operations on matrices stored as lists of rows."""

from __future__ import annotations

Matrix = list[list[float]]


def shape(m: Matrix) -> tuple[int, int]:
    """The number of rows and the number of columns of m."""
    return len(m), (len(m[0]) if m else 0)


def identity(n: int) -> Matrix:
    """The n-by-n identity matrix."""
    return [[1.0 if i == j else 0.0 for j in range(n)] for i in range(n)]


def add(a: Matrix, b: Matrix) -> Matrix:
    """Entry-by-entry sum of two matrices of the same shape."""
    if shape(a) != shape(b):
        raise ValueError(f"shape mismatch: {shape(a)} and {shape(b)}")
    return [[x + y for x, y in zip(ra, rb)] for ra, rb in zip(a, b)]


def scale(m: Matrix, k: float) -> Matrix:
    """Every entry of m multiplied by k."""
    return [[k * x for x in row] for row in m]


def transpose(m: Matrix) -> Matrix:
    """The matrix with rows and columns swapped."""
    return [list(col) for col in zip(*m)]


def trace(m: Matrix) -> float:
    """The sum of the diagonal entries of a square matrix."""
    return sum(m[i][i] for i in range(len(m)))


def matmul(a: Matrix, b: Matrix) -> Matrix:
    """The matrix product of a and b."""
    if shape(a)[1] != shape(b)[0]:
        raise ValueError(f"cannot multiply {shape(a)} by {shape(b)}")
    cols = transpose(b)
    return [[sum(x * y for x, y in zip(row, col)) for col in cols] for row in a]


def format_matrix(m: Matrix) -> str:
    """One line per row, each entry with two decimals, lined up in columns."""
    return format_matrix_places(m, 2)


def format_matrix_places(m: Matrix, places: int) -> str:
    """Like format_matrix, but with the given number of decimals."""
    cells = [[f"{x:.{places}f}" for x in row] for row in m]
    width = max((len(c) for row in cells for c in row), default=0)
    return "\n".join(" ".join(c.rjust(width) for c in row) for row in cells)

